def move_existing_wbs_into_a_plan(apps, schema_editor):
    """WBS data created before plans existed goes into one plan per workspace, tied to all its projects."""
    Workspace = apps.get_model("db", "Workspace")
    Project = apps.get_model("db", "Project")
    Plan = apps.get_model("db", "WbsPlan")
    PlanProject = apps.get_model("db", "WbsPlanProject")
    Phase = apps.get_model("db", "WbsPhase")
    Milestone = apps.get_model("db", "WbsMilestone")
    workspace_ids = set(Phase._base_manager.values_list("workspace_id", flat=True)) | set(
        Milestone._base_manager.values_list("workspace_id", flat=True)
    )
    for workspace in Workspace.objects.filter(id__in=workspace_ids):
        plan = Plan.objects.create(workspace=workspace, name="Main WBS")
        for project in Project.objects.filter(workspace=workspace):
            PlanProject.objects.create(workspace=workspace, plan=plan, project=project)
        Phase._base_manager.filter(workspace=workspace, plan__isnull=True).update(plan=plan)
        Milestone._base_manager.filter(workspace=workspace, plan__isnull=True).update(plan=plan)


